import React, { useState } from "react";
import api from "../services/api";
import { Attendee, EventPayload, CreateEventFormProps } from "../types/event";

export default function CreateEventForm({ onCreated }: CreateEventFormProps) {
  const [name, setName] = useState("");
  const [venue, setVenue] = useState("");
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [attendees, setAttendees] = useState<Attendee[]>([]);
  const [message, setMessage] = useState<string | null>(null); // Success/Error message

  const addAttendee = () => setAttendees(prev => [...prev, { name: "", email: "" }]);
  const updateAttendee = (i: number, field: keyof Attendee, value: string) =>
    setAttendees(prev => prev.map((a, idx) => (idx === i ? { ...a, [field]: value } : a)));

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();

    const payload: EventPayload = {
      name,
      venue,
      startTime: new Date(start).toISOString(),
      endTime: new Date(end).toISOString(),
      attendees,
    };

    try {
      await api.post("/api/Events", payload); // X-Tenant-ID sent automatically
      setMessage("Event created successfully!!"); // Show success message
      onCreated?.();

      // Reset form
      setName("");
      setVenue("");
      setStart("");
      setEnd("");
      setAttendees([]);
    } catch (error: any) {
      console.error("Failed to create event", error);
      setMessage(error?.message || "Failed to create event.."); // Show error message
    }
  };

  return (
    <div>
      {message && <div style={{ marginBottom: "1rem", color: "green" }}>{message}</div>}
      <form onSubmit={submit}>
        <input value={name} onChange={e => setName(e.target.value)} placeholder="Event name" required />
        <input type="datetime-local" value={start} onChange={e => setStart(e.target.value)} required />
        <input type="datetime-local" value={end} onChange={e => setEnd(e.target.value)} required />
        <input value={venue} onChange={e => setVenue(e.target.value)} placeholder="Venue" required />
        <button type="button" onClick={addAttendee}>Add Attendee</button>

        {attendees.map((a, i) => (
          <div key={i}>
            <input placeholder="Name" value={a.name} onChange={e => updateAttendee(i, "name", e.target.value)} required />
            <input placeholder="Email" type="email" value={a.email} onChange={e => updateAttendee(i, "email", e.target.value)} required />
          </div>
        ))}

        <button type="submit">Create Event</button>
      </form>
    </div>
  );
}
